@GameTestHolder("psychedelicrafttests") @PrefixGameTestTemplate(false)
public final class WorldFluidGameTests {
 static final BlockPos P=new BlockPos(8,2,8);
 static boolean same(FluidStack a,FluidStack b){return a.isFluidStackIdentical(b);}
 static void check(boolean value,String message){if(!value)throw new GameTestAssertException(message);}
 static FluidStack brew(PSFluids.Family family){var stack=new FluidStack(family.get(),1000);var tag=stack.getOrCreateTag();tag.putInt("fermentation",3);tag.putInt("maturation",7);tag.putInt("distillation",2);tag.putString("batch","world-attributes");var nested=new CompoundTag();nested.putInt("custom",91);tag.put("extra",nested);return stack;}
 static void basin(GameTestHelper h){for(var at:BlockPos.betweenClosed(1,2,1,14,15,14))h.setBlock(at,Blocks.AIR);for(var at:BlockPos.betweenClosed(0,1,0,15,1,15))h.setBlock(at,Blocks.STONE);for(var at:BlockPos.betweenClosed(0,2,0,15,8,15))if(at.getX()==0||at.getX()==15||at.getZ()==0||at.getZ()==15)h.setBlock(at,Blocks.STONE);}
 static void source(GameTestHelper h,BlockPos relative,FluidStack stack){var block=((WorldFluid)stack.getFluid()).family.block.get();check(block.place(h.getLevel(),h.absolutePos(relative),stack,FluidAction.EXECUTE)==1000,"fixture source placed through production full-bucket entry");}
 static net.minecraftforge.common.util.FakePlayer player(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.randomUUID(),"WorldFluidTest"));p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.setShiftKeyDown(false);return p;}
 static void aim(net.minecraft.world.entity.player.Player p,Vec3 target){var delta=target.subtract(p.getEyePosition());p.setYRot((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));p.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.sqrt(delta.x*delta.x+delta.z*delta.z))));}
 static ItemStack namedBucket(FluidStack fluid){var stack=new ItemStack(Items.BUCKET);stack.setHoverName(Component.literal("Named world bucket"));stack.getOrCreateTag().putInt("custom",37);return new FluidVesselHandler(stack,FluidVessel.BUCKET).replaceContents(fluid);}
 static MashTubBlockEntity vat(GameTestHelper h,BlockPos center){h.setBlock(center,PSBlocks.MASH_TUB.get());for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)if(dx!=0||dz!=0)h.setBlock(center.offset(dx,0,dz),MashTubBlock.wallState(dx,dz));return (MashTubBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(center));}
 @GameTest(template="world_fluid") public static void everyFamilyHasNativeBlocksAndFiniteSourceSemantics(GameTestHelper h){
  basin(h);var pos=h.absolutePos(P);for(var family:PSFluids.all()){var block=family.block.get();check(family.get().defaultFluidState().createLegacyBlock().is(block),"every native source points at its own registered liquid block");check(!family.get().defaultFluidState().canConvertToSource(h.getLevel(),pos)&&family.get().getTickDelay(h.getLevel())==5,"world brews do not create sources and use the native five-tick cadence");check(family.get().is(FluidTags.WATER)==family.waterLike()&&family.flowing.get().is(FluidTags.WATER)==family.waterLike(),"source/flowing native water tags match accepted exclusions");var expected=brew(family);source(h,P,expected);check(same(expected,block.drain(h.getLevel(),pos,FluidAction.EXECUTE)),"every family preserves full arbitrary attributes through source placement/pickup");}h.succeed();
 }
 @GameTest(template="world_fluid") public static void sourceSimulationRefusalAndRepeatedDrainConserveData(GameTestHelper h){
  basin(h);var level=h.getLevel();var pos=h.absolutePos(P);var block=PSFluids.WHEAT.block.get();var fluid=brew(PSFluids.WHEAT);var original=fluid.copy();
  check(block.place(level,pos,fluid,FluidAction.SIMULATE)==1000&&level.getBlockState(pos).isAir()&&same(fluid,original),"source simulation changes neither side");source(h,P,fluid);check(block.place(level,pos,fluid,FluidAction.EXECUTE)==0,"an existing source refuses overwrite");var copy=block.contents(level,pos);copy.getTag().putInt("fermentation",0);check(block.contents(level,pos).getTag().getInt("fermentation")==3,"reads cannot mutate saved attributes");check(same(block.drain(level,pos,FluidAction.SIMULATE),original)&&level.getBlockState(pos).is(block),"source drain simulation preserves the block");
  var wrapper=new FluidBlockWrapper(block,level,pos);check(wrapper.drain(999,FluidAction.EXECUTE).isEmpty()&&wrapper.drain(new FluidStack(PSFluids.COFFEE.get(),1000),FluidAction.EXECUTE).isEmpty(),"partial and wrong-fluid requests cannot consume a source");check(same(wrapper.drain(1000,FluidAction.EXECUTE),original)&&wrapper.drain(1000,FluidAction.EXECUTE).isEmpty()&&level.getBlockEntity(pos)==null,"one whole source drains once and removes its data entity");
  h.setBlock(P,Blocks.STONE);check(block.place(level,pos,fluid,FluidAction.EXECUTE)==0,"solid obstruction refuses placement");h.setBlock(P,Blocks.WATER);check(block.place(level,pos,fluid,FluidAction.EXECUTE)==0&&level.getFluidState(pos).getType()==Fluids.WATER,"foreign fluid is never displaced");h.succeed();
 }
 @GameTest(template="world_fluid") public static void forgeWorldPlacementAndPickupKeepBatchAndNamedContainer(GameTestHelper h){
  basin(h);var level=h.getLevel();var pos=h.absolutePos(P);var expected=brew(PSFluids.RED_GRAPES);var filled=namedBucket(expected);var original=filled.copy();var source=FluidVesselHandler.forCrafting(filled);
  check(FluidUtil.tryPlaceFluid(null,level,InteractionHand.MAIN_HAND,pos,source,expected),"normal Forge world placement succeeds");check(same(expected,PSFluids.RED_GRAPES.block.get().contents(level,pos))&&source.getFluid().isEmpty(),"Forge helper moves full batch data instead of only its fluid state");check(source.getContainer().is(Items.BUCKET)&&source.getContainer().getHoverName().getString().equals("Named world bucket")&&source.getContainer().getTag().getInt("custom")==37&&ItemStack.matches(original,filled),"placement returns named empty and leaves caller's supplied stack unchanged");
  var picked=FluidUtil.tryPickUpFluid(source.getContainer(),null,level,pos,Direction.UP);check(picked.isSuccess()&&level.getBlockState(pos).isAir()&&picked.getResult().getTag().getInt("custom")==37&&picked.getResult().getHoverName().getString().equals("Named world bucket")&&same(expected,FluidVesselHandler.forCrafting(picked.getResult()).getFluid()),"normal Forge pickup retains arbitrary fluid and item data");h.succeed();
 }
 @GameTest(template="world_fluid") public static void nativeBucketItemPickupAndCreativePlacementPreserveTheirContracts(GameTestHelper h){
  basin(h);var level=h.getLevel();var pos=h.absolutePos(P);var expected=brew(PSFluids.JUNIPER);source(h,P,expected);var p=player(h);p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-2);aim(p,pos.getCenter().add(0,.3,0));var empty=namedBucket(FluidStack.EMPTY);p.setItemInHand(InteractionHand.MAIN_HAND,empty);var use=Items.BUCKET.use(level,p,InteractionHand.MAIN_HAND);check(use.getResult().consumesAction()&&level.getBlockState(pos).isAir()&&same(expected,PSItems.FILLED_BUCKET.get().contents(use.getObject()))&&use.getObject().getTag().getInt("custom")==37,"actual native empty-bucket use preserves complete data and original bucket name");
  p.setGameMode(GameType.CREATIVE);var held=namedBucket(expected);var original=held.copy();p.setItemInHand(InteractionHand.MAIN_HAND,held);aim(p,pos.below().getCenter().add(0,.5,0));var placed=PSItems.FILLED_BUCKET.get().use(level,p,InteractionHand.MAIN_HAND);check(placed.getResult().consumesAction()&&ItemStack.matches(original,placed.getObject())&&same(expected,PSFluids.JUNIPER.block.get().contents(level,pos)),"creative filled-bucket use places one complete source and keeps exact held stack");PSFluids.JUNIPER.block.get().drain(level,pos,FluidAction.EXECUTE);h.succeed();
 }
 @GameTest(template="world_fluid") public static void flowingLevelAndAttributesSaveSeparatelyWithoutCreatingSources(GameTestHelper h){
  basin(h);var level=h.getLevel();var pos=h.absolutePos(P);var family=PSFluids.COFFEE;var attrs=new CompoundTag();attrs.putInt("warmth",2);attrs.putString("batch","saved-flow");family.block.get().setFluid(level,pos,family.flowing.get().getFlowing(4,true),attrs);var state=level.getBlockState(pos);var entity=(FluidAttributesBlockEntity)level.getBlockEntity(pos);var saved=entity.saveWithFullMetadata();var restored=new FluidAttributesBlockEntity(pos,state);restored.load(saved);check(restored.attributes().equals(attrs)&&state.getValue(LiquidBlock.LEVEL)==12&&state.getFluidState().getAmount()==8&&state.getFluidState().getValue(FlowingFluid.FALLING)&&!state.getFluidState().isSource()&&family.block.get().drain(level,pos,FluidAction.EXECUTE).isEmpty(),"native falling/level state is independent of complete saved batch data and is not collectible");var snapshot=restored.attributes();snapshot.putInt("warmth",0);check(restored.attributes().getInt("warmth")==2,"saved attribute reads are snapshots");h.succeed();
 }
 @GameTest(template="world_fluid") public static void coffeeRandomTicksCoolSourceAndFlowWithoutDroppingOtherData(GameTestHelper h){
  basin(h);var level=h.getLevel();var pos=h.absolutePos(P);var family=PSFluids.COFFEE;var hot=new FluidStack(family.get(),1000);hot.getOrCreateTag().putInt("warmth",2);source(h,P,hot);for(int expected=1;expected>=0;expected--){level.getFluidState(pos).randomTick(level,pos,level.random);check(PSFluids.warmth(family.block.get().contents(level,pos))==expected,"normal fluid random tick cools coffee one stage");}check(!level.getBlockState(pos).getValue(PhysicalFluidBlock.ATTRIBUTED)&&level.getBlockEntity(pos)==null,"last cooling stage removes an empty attribute entity");
  var attr=new CompoundTag();attr.putInt("warmth",1);attr.putString("batch","keep");family.block.get().setFluid(level,pos,family.flowing.get().getFlowing(6,false),attr);level.getFluidState(pos).randomTick(level,pos,level.random);check(family.block.get().contents(level,pos).getTag().getString("batch").equals("keep")&&!family.block.get().contents(level,pos).getTag().contains("warmth")&&!level.getFluidState(pos).isSource(),"flowing coffee cools without changing its level or unrelated batch fields");h.succeed();
 }
 @GameTest(template="world_fluid",timeoutTicks=180) public static void nativeFallingHorizontalFlowCurrentsAndDrainageCarryAttributes(GameTestHelper h){
  basin(h);var level=h.getLevel();var start=P.above();var expected=brew(PSFluids.WHEAT);source(h,start,expected);
  h.runAtTickTime(30,()->{var below=h.absolutePos(P);var side=below.south();check(level.getFluidState(below).getValue(FlowingFluid.FALLING)&&!level.getFluidState(below).isSource(),"native downward flow has a real falling flag");check(level.getFluidState(side).getAmount()>0&&!level.getFluidState(side).isSource()&&level.getFluidState(side).getFlow(level,side).horizontalDistanceSqr()>0,"native horizontal flowing level and current exist");check(same(expected,PSFluids.WHEAT.block.get().contents(level,side)),"normal scheduled propagation retains arbitrary batch fields");check(PSFluids.WHEAT.block.get().drain(level,side,FluidAction.EXECUTE).isEmpty(),"propagated flowing cells cannot become extra collectible buckets");h.setBlock(start,Blocks.AIR);});
  h.runAtTickTime(150,()->{for(var at:BlockPos.betweenClosed(1,2,1,14,4,14))check(!level.getFluidState(h.absolutePos(at)).getType().isSame(PSFluids.WHEAT.get()),"native flowing cells drain after their source is removed");h.succeed();});
 }
 @GameTest(template="world_fluid",timeoutTicks=80) public static void nativeTwoSourceLayoutDoesNotInventAThirdSource(GameTestHelper h){
  basin(h);source(h,P.west(),brew(PSFluids.WHEAT));source(h,P.east(),brew(PSFluids.WHEAT));h.runAtTickTime(50,()->{var pos=h.absolutePos(P);check(!h.getLevel().getFluidState(pos).isSource()&&PSFluids.WHEAT.block.get().drain(h.getLevel(),pos,FluidAction.EXECUTE).isEmpty(),"native two-source layout remains finite for brews");h.succeed();});
 }
 @GameTest(template="world_fluid",timeoutTicks=80) public static void nonWaterLikeFlowPreservesForeignWaterAndCanSpreadSideways(GameTestHelper h){
  basin(h);h.setBlock(P,Blocks.WATER);source(h,P.above(),brew(PSFluids.KAVA));h.runAtTickTime(40,()->{check(h.getLevel().getFluidState(h.absolutePos(P)).getType()==Fluids.WATER,"native water remains intact under non-water-like brew");check(java.util.stream.Stream.of(Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST).anyMatch(d->h.getLevel().getFluidState(h.absolutePos(P.above().relative(d))).getType().isSame(PSFluids.KAVA.get())),"refused downward replacement still allows native horizontal flow; source="+h.getBlockState(P.above())+" sides="+java.util.stream.Stream.of(Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST).map(d->h.getBlockState(P.above().relative(d))).toList());h.succeed();});
 }
 @GameTest(template="world_fluid") public static void nativeFlowCopiesFirstMatchingNeighborEvenWhenItIsUntagged(GameTestHelper h){
  basin(h);var level=h.getLevel();var pos=h.absolutePos(P);var family=PSFluids.WHEAT;var first=new CompoundTag();first.putString("batch","down-first");var second=new CompoundTag();second.putString("batch","up-second");family.block.get().setFluid(level,pos.below(),family.get().defaultFluidState(),first);family.block.get().setFluid(level,pos.above(),family.get().defaultFluidState(),second);family.block.get().setFluid(level,pos,family.flowing.get().getFlowing(4,false),second);level.getFluidState(pos).tick(level,pos);check(family.block.get().contents(level,pos).getTag().getString("batch").equals("down-first"),"native flow update copies first matching enum neighbor independently of flow level");family.block.get().setFluid(level,pos.below(),family.get().defaultFluidState(),new CompoundTag());level.getFluidState(pos).tick(level,pos);check(!family.block.get().contents(level,pos).hasTag()&&level.getBlockEntity(pos)==null,"an untagged first neighbor clears stale attributes");h.succeed();
 }
 @GameTest(template="world_fluid",timeoutTicks=80) public static void nativeFlowFillsVatWithWholeMatchingBatches(GameTestHelper h){
  basin(h);var vat=vat(h,P);var expected=brew(PSFluids.WHEAT);source(h,P.above(2),expected);h.runAtTickTime(40,()->{var saved=vat.getTank().getFluid();check(saved.getAmount()>=1000&&saved.getAmount()%1000==0&&saved.isFluidEqual(expected)&&h.getLevel().getBlockState(h.absolutePos(P)).is(PSBlocks.MASH_TUB.get()),"native flowing brew enters the vat with all batch fields and never replaces the machine");h.succeed();});
 }
 @GameTest(template="world_fluid",timeoutTicks=80) public static void refusedAndPartialVatInflowNeverDisplacesOrPartiallyFills(GameTestHelper h){
  basin(h);var vat=vat(h,P);var held=brew(PSFluids.WHEAT);held.setAmount(vat.getTank().getCapacity()-500);vat.getTank().replace(held);source(h,P.above(2),brew(PSFluids.WHEAT));h.runAtTickTime(40,()->{check(same(vat.getTank().getFluid(),held)&&h.getLevel().getBlockState(h.absolutePos(P)).is(PSBlocks.MASH_TUB.get()),"a remaining half-bucket of capacity refuses the whole inflow without altering vat contents");h.succeed();});
 }
 @GameTest(template="world_fluid") public static void forgeVatPlacementKeepsBatchAndRefusesPartialSources(GameTestHelper h){
  basin(h);var vat=vat(h,P);var expected=brew(PSFluids.RED_GRAPES);var source=new FluidTank(2000);var small=expected.copy();small.setAmount(500);source.fill(small,FluidAction.EXECUTE);check(!FluidUtil.tryPlaceFluid(null,h.getLevel(),InteractionHand.MAIN_HAND,h.absolutePos(P),source,small)&&source.getFluidAmount()==500&&vat.getTank().isEmpty(),"normal Forge vat placement refuses partial buckets on both sides");source.fill(small,FluidAction.EXECUTE);check(FluidUtil.tryPlaceFluid(null,h.getLevel(),InteractionHand.MAIN_HAND,h.absolutePos(P),source,expected)&&source.isEmpty()&&same(vat.getTank().getFluid(),expected),"normal Forge vat placement retains the full batch rather than reducing it to FluidState");h.succeed();
 }
 @GameTest(template="world_fluid",timeoutTicks=60) public static void realDispenserPlacementAndStackedPickupConserveNamedBuckets(GameTestHelper h){
  basin(h);var level=h.getLevel();var at=new BlockPos(8,3,4);var dest=at.south();h.setBlock(at,Blocks.DISPENSER.defaultBlockState().setValue(DispenserBlock.FACING,Direction.SOUTH));var dispenser=(DispenserBlockEntity)level.getBlockEntity(h.absolutePos(at));var expected=brew(PSFluids.JUNIPER);dispenser.setItem(0,namedBucket(expected));h.setBlock(at.west(),Blocks.REDSTONE_BLOCK);
  h.runAtTickTime(10,()->{check(dispenser.getItem(0).is(Items.BUCKET)&&dispenser.getItem(0).getTag().getInt("custom")==37&&same(expected,PSFluids.JUNIPER.block.get().contents(level,h.absolutePos(dest))),"real dispenser places one attributed source and returns its named empty bucket");h.setBlock(at.west(),Blocks.AIR);var empties=namedBucket(FluidStack.EMPTY);empties.setCount(2);dispenser.setItem(0,empties);});
  h.runAtTickTime(15,()->h.setBlock(at.west(),Blocks.REDSTONE_BLOCK));h.runAtTickTime(25,()->{int empty=0,filled=0;for(int slot=0;slot<9;slot++){var stack=dispenser.getItem(slot);if(stack.is(Items.BUCKET))empty+=stack.getCount();if(stack.is(PSItems.FILLED_BUCKET.get())){filled+=stack.getCount();check(same(expected,PSItems.FILLED_BUCKET.get().contents(stack))&&stack.getTag().getInt("custom")==37,"collected dispenser bucket keeps exact batch and original item fields");}}check(empty==1&&filled==1&&!level.getFluidState(h.absolutePos(dest)).isSource(),"stacked native pickup consumes one empty and collects one source");h.succeed();});
 }
 @GameTest(template="world_fluid") public static void nativeWaterloggingRejectsBrewWithoutLosingItsAttributes(GameTestHelper h){
  basin(h);h.setBlock(P,PSBlocks.JUNIPER_SLAB.get());var expected=brew(PSFluids.WHEAT);var source=new FluidTank(1000);source.fill(expected,FluidAction.EXECUTE);check(!FluidUtil.tryPlaceFluid(null,h.getLevel(),InteractionHand.MAIN_HAND,h.absolutePos(P),source,expected)&&same(source.getFluid(),expected)&&!h.getBlockState(P).getValue(SlabBlock.WATERLOGGED),"native waterlogging cannot silently turn an attributed brew into vanilla water");check(PSBlocks.JUNIPER_SLAB.get().placeLiquid(h.getLevel(),h.absolutePos(P),h.getBlockState(P),Fluids.WATER.defaultFluidState())&&h.getBlockState(P).getValue(SlabBlock.WATERLOGGED),"ordinary native waterlogging remains usable");h.succeed();
 }
 @GameTest(template="world_fluid") public static void netherPlacementVaporizesAllAcceptedWorldFluidTypes(GameTestHelper h){
  var level=h.getLevel().getServer().getLevel(Level.NETHER);check(level!=null,"native Nether exists");var pos=new BlockPos(0,110,0);level.getChunkAt(pos);level.setBlock(pos,Blocks.AIR.defaultBlockState(),3);for(var family:List.of(PSFluids.COFFEE,PSFluids.AGAVE,PSFluids.KAVA,PSFluids.BATH_SALTS)){var expected=brew(family);var source=new FluidTank(1000);source.fill(expected,FluidAction.EXECUTE);check(FluidUtil.tryPlaceFluid(null,level,InteractionHand.MAIN_HAND,pos,source,expected)&&source.isEmpty()&&level.getBlockState(pos).isAir(),"accepted world-fluid vaporization consumes one full bucket and leaves no source, including non-water-like families");}h.succeed();
 }
 @GameTest(template="world_fluid",timeoutTicks=80) public static void nativeDrowningAndBoatBuoyancyRecognizeWaterLikeBrews(GameTestHelper h){
  basin(h);var level=h.getLevel();var family=PSFluids.WHEAT;for(var at:BlockPos.betweenClosed(4,2,4,12,3,12))family.block.get().setFluid(level,h.absolutePos(at),family.get().defaultFluidState(),new CompoundTag());
  var cow=EntityType.COW.create(level);cow.setNoAi(true);cow.setNoGravity(true);cow.setPos(h.absolutePos(P).getCenter().add(2,-.4,0));level.addFreshEntity(cow);
  var boat=ivorius.psychedelicraft.entity.PSEntities.JUNIPER_BOAT.get().create(level);boat.setPos(h.absolutePos(P).getCenter().add(-1,2,0));level.addFreshEntity(boat);
  h.runAtTickTime(35,()->{check(cow.isInFluidType(family.get().getFluidType())&&cow.getAirSupply()<300,"native entity fluid contact and drowning recognize the registered brew type");check(boat.getY()>h.absolutePos(P).getY()+1&&boat.getY()<h.absolutePos(P).getY()+2,"native boat floats at the brew surface through Forge boating support");cow.discard();boat.discard();h.succeed();});
 }
 @GameTest(template="world_fluid",timeoutTicks=60) public static void nativeLavaReactionUsesWaterTagsAndKeepsNonWaterLikeBatches(GameTestHelper h){
  basin(h);var level=h.getLevel();source(h,P,brew(PSFluids.WHEAT));h.setBlock(P.east(),Blocks.LAVA);check(h.getBlockState(P.east()).is(Blocks.OBSIDIAN)&&h.getBlockState(P).is(PSFluids.WHEAT.block.get()),"native adjacent lava source reacts with water-like brew without consuming the brew source; lava="+h.getBlockState(P.east())+" source="+h.getBlockState(P)+" type="+level.getFluidState(h.absolutePos(P))+" water="+level.getFluidState(h.absolutePos(P)).is(FluidTags.WATER));h.setBlock(P.east(),Blocks.AIR);h.setBlock(P,Blocks.AIR);source(h,P,brew(PSFluids.KAVA));h.setBlock(P.east(),Blocks.LAVA);check(h.getBlockState(P.east()).is(Blocks.LAVA)&&h.getBlockState(P).is(PSFluids.KAVA.block.get()),"excluded non-water-like family does not become a water reaction");h.setBlock(P.east(),Blocks.AIR);h.succeed();
 }

 @GameTest(template="world_fluid",timeoutTicks=100) public static void settledFlowReceivesAttributeOnlyUpdatesThroughNativeNeighborTicks(GameTestHelper h){
  basin(h);var level=h.getLevel();source(h,P.above(),brew(PSFluids.WHEAT));h.runAtTickTime(40,()->{var updated=brew(PSFluids.WHEAT);updated.getTag().putString("batch","updated-after-settling");var pos=h.absolutePos(P.above());PSFluids.WHEAT.block.get().setFluid(level,pos,level.getFluidState(pos),updated.getTag());});
  h.runAtTickTime(75,()->{check(PSFluids.WHEAT.block.get().contents(level,h.absolutePos(P)).getTag().getString("batch").equals("updated-after-settling"),"attribute-only changes notify settled native flow without requiring a level change");h.succeed();});
 }

 @GameTest(template="world_fluid") public static void plainWorldMilkPickupRemainsPlaceableInsteadOfBecomingADrink(GameTestHelper h){
  basin(h);var level=h.getLevel();var pos=h.absolutePos(P);var plain=new FluidStack(PSFluids.MILK.get(),1000);source(h,P,plain);var p=player(h);p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-2);aim(p,pos.getCenter().add(0,.3,0));p.setItemInHand(InteractionHand.MAIN_HAND,namedBucket(FluidStack.EMPTY));var pickup=Items.BUCKET.use(level,p,InteractionHand.MAIN_HAND);check(pickup.getResult().consumesAction()&&pickup.getObject().is(PSItems.FILLED_BUCKET.get())&&same(PSItems.FILLED_BUCKET.get().contents(pickup.getObject()),plain),"native plain-milk source pickup returns the accepted placeable world bucket");p.setItemInHand(InteractionHand.MAIN_HAND,pickup.getObject());aim(p,pos.below().getCenter().add(0,.5,0));check(PSItems.FILLED_BUCKET.get().use(level,p,InteractionHand.MAIN_HAND).getResult().consumesAction()&&same(PSFluids.MILK.block.get().contents(level,pos),plain),"plain collected milk places a full source again");var generic=FluidUtil.tryPickUpFluid(namedBucket(FluidStack.EMPTY),null,level,pos,Direction.UP);check(generic.isSuccess()&&generic.getResult().is(PSItems.FILLED_BUCKET.get())&&same(PSItems.FILLED_BUCKET.get().contents(generic.getResult()),plain)&&generic.getResult().getTag().getInt("custom")==37,"generic Forge world pickup also preserves plain milk placement and named-container data");h.succeed();
 }

}
